export class MemStorage implements IStorage {
  private investments: Map<string, Investment>;

  constructor() {
    this.investments = new Map();
    for (const inv of rawInvestments) {
      this.investments.set(inv.id, { ...inv });
    }
  }

  async getInvestments(): Promise<Investment[]> {
    return Array.from(this.investments.values()).sort(
      (a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()
    );
  }

  async assignInvestment(
    investmentId: string,
    assignTo: "Grant" | "Haythem"
  ): Promise<Investment | null> {
    const inv = this.investments.get(investmentId);
    if (!inv) return null;

    if (inv.assignedTo !== null && inv.assignedTo !== assignTo) {
      inv.assignedTo = null;
      return inv;
    }

    inv.assignedTo = assignTo;
    return inv;
  }
}

export const storage = new MemStorage();